<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'; import { Plus,Save,Trash2 } from 'lucide-vue-next'; import { useRoute,useRouter } from 'vue-router'
import AppButton from '@/components/common/AppButton.vue'; import AppBreadcrumb from '@/components/layout/AppBreadcrumb.vue'; import { customerService } from '@/services/customer.service'; import { itemService } from '@/services/item.service'; import { salesInvoiceService } from '@/services/sales-invoice.service'; import { taxCodeService } from '@/services/tax-code.service'; import { warehouseService } from '@/services/warehouse.service'; import { useNotificationStore } from '@/stores/notification.store'; import type { CustomerRecord,ItemRecord,TaxCodeRecord,WarehouseRecord } from '@/types/master'; import type { SalesInvoiceLinePayload,SalesInvoicePayload } from '@/types/sales'; import { getApiErrorMessage } from '@/utils/error'
interface EditLine extends SalesInvoiceLinePayload{key:number}; const route=useRoute(),router=useRouter(),notifications=useNotificationStore(); const id=computed(()=>Number(route.params.id)||null),isEdit=computed(()=>Boolean(id.value)); const customers=ref<CustomerRecord[]>([]),warehouses=ref<WarehouseRecord[]>([]),items=ref<ItemRecord[]>([]),taxes=ref<TaxCodeRecord[]>([]),loading=ref(false),saving=ref(false),error=ref('');let key=1
const today=new Date().toISOString().slice(0,10);const form=reactive({invoice_date:today,due_date:today,customer_id:0,warehouse_id:0,reference:'',notes:'',currency:'IDR',exchange_rate:1,version:1,lines:[] as EditLine[]})
const add=()=>form.lines.push({key:key++,item_id:0,description:null,quantity:1,unit_id:0,unit_price:0,discount:0,discount_percent:0,tax_code_id:null}); const chooseCustomer=()=>{const value=customers.value.find(x=>x.id===form.customer_id);if(value){form.currency=value.currency??'IDR';const due=new Date(`${form.invoice_date}T00:00:00Z`);due.setUTCDate(due.getUTCDate()+Number(value.payment_term_days??0));form.due_date=due.toISOString().slice(0,10)}};const chooseItem=(line:EditLine)=>{const item=items.value.find(x=>x.id===line.item_id);if(item){line.unit_id=Number(item.unit_id);line.unit_price=Number(item.selling_price??0);line.description=item.name}}
const lineAmount=(line:EditLine)=>{const gross=Number(line.quantity)*Number(line.unit_price),discount=Number(line.discount)||gross*Number(line.discount_percent)/100,tax=taxes.value.find(x=>x.id===line.tax_code_id);return Math.max(0,gross-discount)*(1+Number(tax?.rate??0)/100)};const total=computed(()=>form.lines.reduce((sum,line)=>sum+lineAmount(line),0));const money=(v:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:form.currency,maximumFractionDigits:2}).format(v)
const payload=():SalesInvoicePayload=>({invoice_date:form.invoice_date,due_date:form.due_date,customer_id:form.customer_id,warehouse_id:form.warehouse_id||null,reference:form.reference||null,notes:form.notes||null,currency:form.currency,exchange_rate:Number(form.exchange_rate),version:form.version,lines:form.lines.map(({key:_,...line})=>line)})
const load=async()=>{loading.value=true;error.value='';try{const [c,w,i,t]=await Promise.all([customerService.list({limit:100}),warehouseService.list({limit:100}),itemService.list({limit:100}),taxCodeService.list({limit:100})]);customers.value=c.data;warehouses.value=w.data;items.value=i.data;taxes.value=t.data;if(id.value){const invoice=await salesInvoiceService.get(id.value);if(invoice.sales_order_id)throw new Error('Invoice hasil sales order tidak dapat diedit langsung.');Object.assign(form,{invoice_date:invoice.invoice_date.slice(0,10),due_date:invoice.due_date.slice(0,10),customer_id:invoice.customer_id,warehouse_id:invoice.warehouse_id??0,reference:invoice.reference??'',notes:invoice.notes??'',currency:invoice.currency,exchange_rate:Number(invoice.exchange_rate),version:invoice.version,lines:(invoice.lines??[]).map(line=>({key:key++,item_id:line.item_id,description:line.description,quantity:Number(line.quantity),unit_id:line.unit_id,unit_price:Number(line.unit_price),discount:Number(line.discount),discount_percent:Number(line.discount_percent),tax_code_id:line.tax_code_id}))})}else add()}catch(e){error.value=getApiErrorMessage(e,'Form sales invoice gagal dimuat.')}finally{loading.value=false}}
const save=async()=>{error.value='';if(!form.customer_id||!form.lines.length||form.lines.some(x=>!x.item_id||x.quantity<=0)){error.value='Pelanggan dan minimal satu baris item valid wajib diisi.';return}if(form.lines.some(x=>x.discount>0&&x.discount_percent>0)){error.value='Gunakan diskon nominal atau persentase pada setiap baris.';return}saving.value=true;try{if(id.value)await salesInvoiceService.update(id.value,payload());else await salesInvoiceService.create(payload());notifications.push(`Sales invoice berhasil ${id.value?'diperbarui':'dibuat'}.`);await router.push('/sales/invoices')}catch(e){error.value=getApiErrorMessage(e,'Sales invoice gagal disimpan.');notifications.push(error.value,'error')}finally{saving.value=false}};onMounted(load)
</script>
<template><div><AppBreadcrumb/><div class="mb-6"><h1 class="text-2xl font-bold">{{isEdit?'Edit':'Buat'}} Sales Invoice</h1><p class="mt-1 text-sm text-slate-500">Invoice baru tersimpan sebagai Draft; jurnal dan stok berubah hanya setelah approval dan posting.</p></div><p v-if="error" class="mb-4 rounded bg-red-50 p-3 text-sm text-red-700">{{error}}</p><div v-if="loading" class="panel space-y-3 p-5"><div v-for="i in 6" :key="i" class="h-10 animate-pulse rounded bg-slate-100"/></div><form v-else class="space-y-5" @submit.prevent="save"><section class="panel grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-4"><label class="form-label">Tanggal Invoice<input v-model="form.invoice_date" required type="date" class="field mt-1"/></label><label class="form-label">Jatuh Tempo<input v-model="form.due_date" required type="date" class="field mt-1"/></label><label class="form-label">Pelanggan<select v-model.number="form.customer_id" required class="field mt-1" @change="chooseCustomer"><option :value="0">Pilih pelanggan</option><option v-for="x in customers" :key="x.id" :value="x.id">{{x.code}} · {{x.name}}</option></select></label><label class="form-label">Gudang<select v-model.number="form.warehouse_id" class="field mt-1"><option :value="0">Tanpa gudang</option><option v-for="x in warehouses" :key="x.id" :value="x.id">{{x.code}} · {{x.name}}</option></select></label><label class="form-label">Referensi<input v-model="form.reference" class="field mt-1" maxlength="100"/></label><label class="form-label">Mata Uang<input v-model="form.currency" class="field mt-1 uppercase" maxlength="3" readonly/></label><label class="form-label">Kurs<input v-model.number="form.exchange_rate" required min="0.00000001" step="0.00000001" type="number" class="field mt-1"/></label><label class="form-label md:col-span-2 xl:col-span-1">Catatan<textarea v-model="form.notes" class="field mt-1 min-h-10"/></label></section><section class="panel overflow-hidden"><header class="flex items-center justify-between border-b p-4"><h2 class="font-semibold">Baris Invoice</h2><AppButton variant="secondary" :icon="Plus" @click="add">Tambah Baris</AppButton></header><div class="overflow-x-auto"><table class="w-full min-w-[1050px] text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-3">Item</th><th class="p-3">Deskripsi</th><th class="p-3">Qty</th><th class="p-3">Harga</th><th class="p-3">Diskon</th><th class="p-3">Diskon %</th><th class="p-3">Pajak</th><th class="p-3 text-right">Total</th><th></th></tr></thead><tbody class="divide-y"><tr v-for="line in form.lines" :key="line.key"><td class="p-2"><select v-model.number="line.item_id" required class="field min-w-48" @change="chooseItem(line)"><option :value="0">Pilih item</option><option v-for="x in items" :key="x.id" :value="x.id">{{x.sku}} · {{x.name}}</option></select></td><td class="p-2"><input v-model="line.description" class="field min-w-40"/></td><td class="p-2"><input v-model.number="line.quantity" required type="number" min="0.0001" step="0.0001" class="field w-24 text-right"/></td><td class="p-2"><input v-model.number="line.unit_price" required type="number" min="0" step="0.01" class="field w-32 text-right"/></td><td class="p-2"><input v-model.number="line.discount" type="number" min="0" step="0.01" class="field w-28 text-right"/></td><td class="p-2"><input v-model.number="line.discount_percent" type="number" min="0" max="100" step="0.0001" class="field w-24 text-right"/></td><td class="p-2"><select v-model.number="line.tax_code_id" class="field min-w-32"><option :value="null">Tanpa pajak</option><option v-for="x in taxes" :key="x.id" :value="x.id">{{x.code}} ({{x.rate}}%)</option></select></td><td class="p-2 text-right font-semibold">{{money(lineAmount(line))}}</td><td class="p-2"><button type="button" class="rounded p-2 text-red-600 hover:bg-red-50" @click="form.lines=form.lines.filter(x=>x.key!==line.key)"><Trash2 class="h-4 w-4"/></button></td></tr></tbody></table></div><div v-if="!form.lines.length" class="p-6 text-center text-sm text-slate-500">Belum ada baris invoice.</div><footer class="flex justify-end border-t bg-slate-50 p-4"><div class="text-right"><p class="text-xs uppercase text-slate-500">Estimasi total</p><p class="text-xl font-bold">{{money(total)}}</p></div></footer></section><div class="flex justify-end gap-2"><AppButton variant="secondary" :disabled="saving" @click="router.push('/sales/invoices')">Batal</AppButton><AppButton type="submit" :icon="Save" :loading="saving">Simpan Draft</AppButton></div></form></div></template>
